def bs(arr, target):
    """Search for a target element in a sorted array using binary search."""
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def merge_sort(arr):
    """Sort a list using divide-and-conquer merge sort algorithm."""
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    return merge(left, right)

def merge(left, right):
    result = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    result.extend(left[i:])
    result.extend(right[j:])
    return result

def flatten_nested_list(nested):
    """Recursively flatten a deeply nested list into a single 1D list."""
    flat = []
    for item in nested:
        if isinstance(item, list):
            flat.extend(flatten_nested_list(item))
        else:
            flat.append(item)
    return flat

class LRUCache:
    """Implement Least Recently Used (LRU) cache with O(1) get and put."""
    def __init__(self, capacity: int):
        from collections import OrderedDict
        self.cache = OrderedDict()
        self.capacity = capacity

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

def connect_database(host, port, dbname, user, password):
    """Establish connection to a PostgreSQL database and execute queries."""
    import psycopg2
    conn = psycopg2.connect(host=host, port=port, dbname=dbname, user=user, password=password)
    return conn

def execute_query(conn, sql, params=None):
    """Execute a SQL query with parameters and fetch results."""
    with conn.cursor() as cur:
        cur.execute(sql, params)
        if cur.description:
            return cur.fetchall()
        conn.commit()

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI(title='Item Store')

class Item(BaseModel):
    name: str
    price: float
    tags: list[str] = []

db: dict[str, dict] = {}

@app.post('/items/{item_id}', status_code=201)
def create_item(item_id: str, item: Item):
    """Create a new item in the store with request body validation."""
    if item_id in db:
        raise HTTPException(status_code=409, detail='Item already exists')
    db[item_id] = item.model_dump()
    return {'item_id': item_id, **db[item_id]}

@app.get('/items/{item_id}')
def get_item(item_id: str):
    """Retrieve an item by its unique ID."""
    if item_id not in db:
        raise HTTPException(status_code=404, detail='Item not found')
    return db[item_id]

def bfs_shortest_path(graph, start, goal):
    """Find the shortest path between start and goal nodes using Breadth-First Search."""
    from collections import deque
    queue = deque([(start, [start])])
    visited = set([start])
    while queue:
        node, path = queue.popleft()
        if node == goal:
            return path
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))
    return None

import pytest

def calculate_discount(price: float, discount_percent: float) -> float:
    """Calculate discounted price with validation."""
    if not (0 <= discount_percent <= 100):
        raise ValueError('Discount must be between 0 and 100')
    return round(price * (1 - discount_percent / 100), 2)

@pytest.mark.parametrize('price, discount, expected', [
    (100.0, 10.0, 90.0),
    (50.0, 0.0, 50.0),
    (200.0, 50.0, 100.0),
])
def test_calculate_discount(price, discount, expected):
    """Test discount calculation with parameterized test cases."""
    assert calculate_discount(price, discount) == expected

def two_sum(nums: list[int], target: int) -> list[int]:
    """Find indices of two numbers that add up to target using hash map in O(N)."""
    seen = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            return [seen[complement], i]
        seen[num] = i
    return []

from functools import lru_cache

@lru_cache(maxsize=128)
def fibonacci_memoized(n: int) -> int:
    """Calculate nth Fibonacci number with memoization to avoid exponential complexity."""
    if n < 2:
        return n
    return fibonacci_memoized(n - 1) + fibonacci_memoized(n - 2)

def fibonacci_dp(n: int) -> int:
    """Calculate nth Fibonacci number using dynamic programming with O(1) space."""
    if n < 2:
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

import re

def validate_and_parse_email(email: str) -> dict:
    """Validate an email address syntax and extract username and domain components."""
    pattern = r'^(?P<username>[a-zA-Z0-9_.+-]+)@(?P<domain>[a-zA-Z0-9-]+\.[a-zA-Z0-9-.]+)$'
    match = re.match(pattern, email.strip())
    if match:
        return {'valid': True, **match.groupdict()}
    return {'valid': False, 'username': None, 'domain': None}

def cosine_similarity(u, v):
    """Compute cosine similarity between two 1D numerical vectors."""
    import numpy as np
    dot = np.dot(u, v)
    norm_u = np.linalg.norm(u)
    norm_v = np.linalg.norm(v)
    if norm_u == 0 or norm_v == 0:
        return 0.0
    return float(dot / (norm_u * norm_v))

def batch_pairwise_cosine(embeddings):
    """Compute pairwise cosine similarity matrix for a batch of embeddings."""
    import numpy as np
    norms = np.linalg.norm(embeddings, axis=1, keepdims=True)
    normalized = embeddings / np.maximum(norms, 1e-12)
    return np.dot(normalized, normalized.T)

class Stack:
    """Implement a LIFO Stack with push, pop, peek, and size methods."""
    def __init__(self):
        self._items = []

    def push(self, item):
        self._items.append(item)

    def pop(self):
        if not self._items:
            raise IndexError('pop from empty stack')
        return self._items.pop()

    def peek(self):
        if not self._items:
            raise IndexError('peek from empty stack')
        return self._items[-1]

    def is_empty(self):
        return len(self._items) == 0

    def size(self):
        return len(self._items)

import time
from functools import wraps

def retry_with_backoff(max_retries: int = 3, initial_delay: float = 1.0, factor: float = 2.0):
    """Decorator that retries an operation upon exception using exponential backoff."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            delay = initial_delay
            for attempt in range(1, max_retries + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as exc:
                    if attempt == max_retries:
                        raise
                    time.sleep(delay)
                    delay *= factor
        return wrapper
    return decorator
